import { Effect } from "effect"
import { and, eq, inArray } from "drizzle-orm"
import { Database } from "../database/Database.js"
import { exportJobs } from "../database/schema.js"
import { ExportStorage } from "./ExportStorage.js"

export interface PurgeExport {
  readonly id: string
  readonly objectKey: string
}

export const purgeExports = (
  workspaceId: string,
  exports: ReadonlyArray<PurgeExport>
) =>
  Effect.gen(function*() {
    if (exports.length === 0) {
      return { deleted: 0 }
    }

    const database = yield* Database
    const storage = yield* ExportStorage

    yield* Effect.tryPromise(() =>
      database.client
        .delete(exportJobs)
        .where(and(
          eq(exportJobs.workspaceId, workspaceId),
          inArray(exportJobs.id, exports.map((item) => item.id))
        ))
    )
    yield* storage.removeMany(exports.map((item) => item.objectKey))

    return { deleted: exports.length }
  })
